// Entry point. Serves files from the embedded FILES map (generated by build.mjs from public/)
// behind the Basic Auth gate in gate.js.
import { checkAuth, unauthorized } from './gate.js';
import { FILES } from './files.js';

const TYPES = { html: 'text/html; charset=utf-8', css: 'text/css; charset=utf-8', js: 'text/javascript; charset=utf-8', json: 'application/json; charset=utf-8' };

export default {
  async fetch(request, env) {
    if (!checkAuth(request, env)) return unauthorized();
    const url = new URL(request.url);
    let path = decodeURIComponent(url.pathname);
    if (path.endsWith('/')) path += 'index.html';
    const body = FILES[path];
    if (body === undefined) return new Response('Not found', { status: 404, headers: { 'Cache-Control': 'no-store' } });
    const ext = path.split('.').pop();
    return new Response(body, {
      headers: {
        'Content-Type': TYPES[ext] || 'application/octet-stream',
        'Cache-Control': 'private, no-cache',
        'X-Robots-Tag': 'noindex, nofollow',
        'X-Content-Type-Options': 'nosniff',
      },
    });
  },
};
